"""Bias-removal round: transcripts generated by an INDEPENDENT LLM (via
OpenRouter chat/completions) — not by our scripts — with needles WE plant.

The generator is told the exact facts that must appear verbatim; we verify
them post-generation (retry on miss), then the standard pipeline
(pruners/jev_prune.py + score.py) measures whether compression preserves them.

Usage:
    needs the `openrouter` skill (Secure Vault credential); no raw keys
    python3 gen_llm_inputs.py --model google/gemini-2.5-flash --n 3
    # swap --model for any OpenRouter model to remove generator bias further

Output: inputs/llm_<scenario>_<i>.json  (same schema as the other inputs)
"""
import argparse
import json
import os
import sys
import urllib.request

HERE = os.path.dirname(os.path.abspath(__file__))
OUT_DIR = os.path.join(HERE, "inputs")

API_URL = "https://openrouter.ai/api/v1/chat/completions"

SCENARIOS = [
    {
        "id": "llm_sre",
        "task": "Diagnose and fix the OOM crash in the payments service",
        "needles": [
            "OutOfMemoryError: Java heap space at com.acme.payments.LedgerWriter.flush",
            "heap dump written to /var/crash/payments-2026-09-22.hprof",
            "Xmx currently 2g, recommendation 8g",
        ],
        "brief": ("an SRE agent debugging an OOM crash: kubectl logs, heap dump "
                  "analysis, config reads. Include realistic redundancy: the agent "
                  "re-runs kubectl logs --tail twice, re-reads the deployment yaml, "
                  "and pastes 2-3 long irrelevant stack traces from other pods."),
    },
    {
        "id": "llm_codebase",
        "task": "Find where the NullPointerException in charge() originates",
        "needles": [
            "charge = self.processor.charge(amount) # raises NullPointerException when token is None",
            "def charge(self, amount, token=None):",
            "processor = PaymentProcessor(api_key)",
        ],
        "brief": ("a codebase-exploration agent hunting an NPE: grep results, "
                  "file reads with line numbers, repeated searches with slightly "
                  "different patterns, some dead-end files that contain nothing "
                  "relevant."),
    },
    {
        "id": "llm_dup",
        "task": "Triage failing CI: same test command run across 4 services",
        "needles": [
            "FAILED tests/test_billing.py::test_refund_idempotent - assert 402 == 200",
            "coverage gate: 87.3% (required 90%)",
            "service auth is the only red service",
        ],
        "brief": ("a triage agent running the same pytest command against 4 "
                  "services with near-identical output, plus one service whose "
                  "output differs in exactly the failing test line. Heavy "
                  "near-duplication is intentional."),
    },
]


def chat(model, system, user, max_tokens=6000):
    """Generate via the openrouter skill (stored credential, authd surrogate)."""
    import subprocess
    skill = os.path.expanduser("~/workspace/skills/openrouter/bin/or_chat.py")
    out = subprocess.run(
        [sys.executable, skill, "--model", model, "--system", system,
         "--message", user, "--max-tokens", str(max_tokens)],
        capture_output=True, text=True, timeout=600)
    if out.returncode:
        raise RuntimeError(f"or_chat.py failed: {out.stderr[-300:]}")
    return out.stdout


def extract_messages(text):
    """Pull the JSON messages array out of the model's reply."""
    start = text.find("[")
    end = text.rfind("]")
    if start == -1 or end == -1:
        raise ValueError("no JSON array in reply")
    return json.loads(text[start:end + 1])


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--model", default="google/gemini-2.5-flash")
    ap.add_argument("--n", type=int, default=1,
                    help="copies per scenario (vary temperature effects)")
    args = ap.parse_args()

    # auth: uses the openrouter skill (stored credential via authd); no raw keys

    system = ("You generate realistic coding-agent transcripts for compression "
              "benchmarks. Reply with ONLY a JSON array of message objects "
              "{\"role\": ..., \"content\": ...}; roles: user, assistant, tool. "
              "No markdown fences, no commentary.")
    os.makedirs(OUT_DIR, exist_ok=True)

    for sc in SCENARIOS:
        for i in range(args.n):
            needle_list = "\n".join(f"- {n}" for n in sc["needles"])
            user = (f"Task: {sc['task']}\n\nGenerate a transcript of ~60-90 tool "
                    f"calls. {sc['brief']}\n\nThese facts MUST appear VERBATIM "
                    f"(character-for-character) somewhere in tool outputs:\n"
                    f"{needle_list}\n\nFirst message must be the user stating the task.")
            messages = None
            for attempt in range(3):
                try:
                    messages = extract_messages(chat(args.model, system, user, args.max_tokens))
                    blob = json.dumps(messages)
                    missing = [n for n in sc["needles"] if n not in blob]
                    if not missing:
                        break
                    print(f"  retry {attempt+1}: missing {missing}", file=sys.stderr)
                    messages = None
                except Exception as e:
                    print(f"  attempt {attempt+1} failed: {e}", file=sys.stderr)
            if messages is None:
                print(f"SKIP {sc['id']}: generator could not plant needles", file=sys.stderr)
                continue
            doc = {"id": f"{sc['id']}_{i}" if args.n > 1 else sc["id"],
                   "task": sc["task"], "messages": messages,
                   "evidence": sc["needles"]}
            path = os.path.join(OUT_DIR, doc["id"] + ".json")
            json.dump(doc, open(path, "w"))
            toks = len(json.dumps(messages)) // 4
            print(f"{doc['id']}: ~{toks} tokens (chars/4), "
                  f"{len(sc['needles'])}/{len(sc['needles'])} needles planted -> {path}")


if __name__ == "__main__":
    main()
